cat > /tmp/test-regex.mjs << 'EOF'
const formula = 'sqrt(מרחק בריבוע)';
const labels = [{label: 'מרחק בריבוע', idx: 13}];
const sorted = labels.slice().sort((a, b) => b.label.length - a.label.length);

let e = ' ' + formula + ' ';
console.log('1. After padding:', JSON.stringify(e));

for (const f of sorted) {
  e = e.split(f.label).join(` @${f.idx}@ `);
}
console.log('2. After field replacement:', JSON.stringify(e));

const numericFuncs = new Set(['sqrt']);
for (const fn of numericFuncs) {
  const oldE = e;
  e = e.replace(new RegExp(`\\b${fn}\\s*\\(\\s*@`, 'g'), `@func:${fn}@(`);
  console.log(`3. After func replacement (${fn}):`, JSON.stringify(e), oldE === e ? '(no change)' : '');
}

const residue = e.replace(/@\d+@/g, ' ').replace(/@func:\w+@/g, ' ').replace(/[0-9.+\-*/()\s]/g, '');
console.log('4. Residue check:', JSON.stringify(residue), residue.trim().length ? 'FAILED' : 'passed');

let dart = e.replace(/@(\d+)@/g, "(num.tryParse(_v[$1] ?? '') ?? 0)").trim();
console.log('5. After field index replacement:', JSON.stringify(dart));

dart = dart.replace(/@func:sqrt@/g, 'sqrt');
console.log('6. After func marker replacement:', JSON.stringify(dart));

const hasHebrewOrAt = /@|[֐-׿]/.test(dart);
console.log('7. Final check (no @ or Hebrew):', !hasHebrewOrAt ? 'passed' : 'FAILED');
EOF
node /tmp/test-regex.mjs
